                            /** @enum {string} */
                            type: "INCOME" | "FIXED_EXPENSE" | "VARIABLE_EXPENSE" | "SAVING" | "INVESTMENT" | "DEBT";
                            /** Format: uuid */
                            categoryId: string;
                            /** @description String decimal con 2 decimales (`"25.90"`). Siempre positivo: el signo lo da `type`. */
                            amount: string;
